local SKILLS = { "Attack1", "Attack2", "Attack3", "Attack4", "Attack5", "Roar1", "Roar2", "Utility", "Overdrive" }
local function live() return Workspace:FindFirstChild("Live") end
local function rootOf(m) return m and (m.PrimaryPart or m:FindFirstChild("HumanoidRootPart")) end
local function alive(m) local h = m and m:FindFirstChildWhichIsA("Humanoid"); return h ~= nil and h.Health > 0 end
local function myModel() local l = live(); return l and l:FindFirstChild(lp.Name) end
local function currentKaiju()
    local d = RS:FindFirstChild("Data")
    d = d and d:FindFirstChild(lp.UserId .. "_Data")
    local ck = d and d:FindFirstChild("CurrentKaiju")
    return ck and ck.Value ~= "" and ck.Value or nil
end
-- beams = moves with HitAir and no HitboxData in KaijuData (e.g. "Burst Atomic Ray", "Gojira Ray")
local function detectBeams()
    local out = {}
    local kn = currentKaiju()
    local kd = RS:FindFirstChild("Shared")
    kd = kd and kd:FindFirstChild("KaijuData")
    local mod = kd and kn and kd:FindFirstChild(kn)
    if not mod then return out end
    local ok, data = pcall(require, mod)
    if not ok or type(data) ~= "table" then return out end
    local t = type(data.KaijuData) == "table" and data.KaijuData or data
    for _, key in ipairs(SKILLS) do
        local s = type(t.AttackStatics) == "table" and t.AttackStatics[key]
        if type(s) == "table" and s.HitAir ~= nil and s.HitboxData == nil then out[#out + 1] = key end
    end
    return out
end
local function playerNames()
    local n = {}
    for _, p in ipairs(Players:GetPlayers()) do if p ~= lp then n[#n + 1] = p.Name end end
    table.sort(n)
    return n
end

