local function findBoss()
    local lf = live()
    if not lf then return nil end
    for _, m in ipairs(lf:GetChildren()) do
        if m:GetAttribute("IsBoss") == true and alive(m) then return m end
    end
end
local function pickTarget()
    local lf = live()
    if not lf then return nil end
    local mode = Opt.beam_mode.Value
    if mode == "Boss" then return findBoss() end
    if mode == "Boss > Nearest" then
        local b = findBoss()
        if b then return b end
    end
    if mode == "Selected Player" then
        local m = lf:FindFirstChild(Opt.beam_player.Value or "")
        return alive(m) and m or nil
    end
    local me = rootOf(myModel())
    local cam = Workspace.CurrentCamera
    local mp = UIS:GetMouseLocation()
    local maxR = Opt.beam_range.Value
    local best, bestD
    for _, m in ipairs(lf:GetChildren()) do
        if m.Name ~= lp.Name and m:GetAttribute("IsBoss") ~= true and Players:FindFirstChild(m.Name) and alive(m) then
            local r = rootOf(m)
            if r and me and (r.Position - me.Position).Magnitude <= maxR then
                local d
                if mode == "Nearest To Cursor" then
                    local sp, on = cam:WorldToViewportPoint(r.Position)
                    if on then d = (Vector2.new(sp.X, sp.Y) - mp).Magnitude end
                else
                    d = (r.Position - me.Position).Magnitude
                end
                if d and (not bestD or d < bestD) then best, bestD = m, d end
            end
        end
    end
    return best
end
local BODY = { "CamPart", "UpperBody", "MainBody", "Chest", "UpperTorso", "Torso", "Body" }
local partCache = setmetatable({}, { __mode = "k" })
local function aimPart(m)
    local which = Opt.beam_part.Value
    local c = partCache[m]
    if c and c.which == which and c.part.Parent then return c.part end
    local part
    if which == "Head" then
        local h = m:FindFirstChild("Head", true)
        if h and h:IsA("BasePart") then part = h end
    elseif which == "Body" then
        for _, n in ipairs(BODY) do
            local p = m:FindFirstChild(n, true)
            if p and p:IsA("BasePart") then part = p; break end
        end
    end
    part = part or rootOf(m)
    if part then partCache[m] = { which = which, part = part } end
    return part
end

