            end
        end
        return oldIdx(self, k)
    end))
    local oldNc
    oldNc = hookmm(game, "__namecall", ncc(function(self, ...)
        if S.spoof and GetMousePos and self == GetMousePos and not cc() and ncm() == "FireServer" then
