end

local function beaming() return S.beamOn and os.clock() - S.beamAt < 15 end
track(RunService.Heartbeat:Connect(function()
    if not S.run then return end
    local t = (Toggles.beam_aim.Value or Toggles.beam_cam.Value) and pickTarget() or nil
    S.target = t
    local part = t and aimPart(t)
    if part then
        local p = part.Position + part.AssemblyLinearVelocity * Opt.beam_lead.Value
        S.aimPos = p
        local cam = Workspace.CurrentCamera
        local dir = p - cam.CFrame.Position
        S.aimCF = dir.Magnitude > 0.1 and CFrame.lookAt(p, p + dir.Unit) or CFrame.new(p)
    else
        S.aimPos, S.aimCF = nil, nil
    end
    S.spoof = Toggles.beam_aim.Value and S.aimPos ~= nil and (beaming() or Opt.beam_when.Value == "Always")
end))

RunService:BindToRenderStep("CW_BeamCam", Enum.RenderPriority.Camera.Value + 1, function()
    if not (S.run and Toggles.beam_cam.Value and S.aimPos) then return end
    if Opt.beam_camwhen.Value ~= "Always" and not beaming() then return end
    local cam = Workspace.CurrentCamera
    cam.CFrame = CFrame.lookAt(cam.CFrame.Position, S.aimPos)
end)

task.spawn(function()
    local lastSp, lastT = 0, os.clock()
    while S.run do
        pcall(function()
