            end
            local now = os.clock()
            S.rate = math.floor((S.spoofs - lastSp) / math.max(now - lastT, 0.01))
            lastSp, lastT = S.spoofs, now
            local me = rootOf(myModel())
            local r = rootOf(t)
            local dist = (me and r) and math.floor((r.Position - me.Position).Magnitude) or -1
            lblStat:SetText(("Target: %s  |  %s studs"):format(t and t.Name or "none", dist >= 0 and tostring(dist) or "-"))
            lblBeam:SetText(("Beam: %s  |  aim spoofed %d/s"):format(beaming() and "ON" or "off", S.rate))
            local keys = detectBeams()
            lblKeys:SetText("Detected beams: " .. (#keys > 0 and table.concat(keys, ", ") or "none (pick manually)"))
            if Toggles.beam_auto.Value and t and not beaming() and dist >= 0 and dist <= Opt.beam_firerange.Value then
                for _, k in ipairs(beamKeys()) do
                    if now >= (S.cdUntil[k] or 0) then
                        CombatRemote:FireServer("UseSkill", k)
                        S.cdUntil[k] = now + 1.5
                        break
                    end
                end
            end
        end)
        task.wait(0.25)
    end
end)

